    css: "/* From Uiverse.io by Mhyar-nsi - Tags: blue, button, hover, ring */\nbutton {\n  font-family: monospace;\n  background-color: #f3f7fe;\n  color: #3b82f6;\n  border: none;\n  border-radius: 8px;\n  width: 100px;\n  height: 45px;\n  transition: .3s;\n}\n\nbutton:hover {\n  background-color: #3b82f6;\n  box-shadow: 0 0 0 5px #3b83f65f;\n  color: #fff;\n}",
