    slug: "rudra1725_splendid-fish-19",
    title: "Splendid Fish",
    author: "Rudra1725",
    html: "<button class=\"btn1\">&gt; Send Message</button>",
    css: "/* From Uiverse.io by Rudra1725  - Tags: simple, material design, 3d, button, hover, active */\n.btn1 {\n  color: black;\n  background-color: white;\n  border: solid wheat 2px;\n  border-radius: 9px;\n  font-size: 19px;\n  padding: 12px;\n  box-shadow: inset 0 0 4px black;\n  font-weight: 500;\n  transition: 400ms;\n}\n.btn1:hover {\n  transition: 400ms;\n  box-shadow: inset 0 0 6px black, 0 0 10px wheat;\n}\n.btn1:active {\n  transition: 50ms;\n  box-shadow: inset 0 0 0px black, 0 0 10px wheat;\n}",
