    css: "/* From Uiverse.io by ercnersoy - Tags: button */\nbutton {\n  padding: 0 20px 0 10px;\n  border-radius: 10px;\n  box-shadow: 0px 0px 5px 7px #e7413373;\n  background-color: #e74133;\n  color: white;\n  font-size: 17px;\n  border: none;\n  display: flex;\n  align-items: center;\n  transition: all .5s ease-in-out;\n  letter-spacing: 2px;\n}\n\nbutton:hover {\n  background-color: #f54d3e;\n  transition: all .5s ease-in-out;\n  box-shadow: 0px 0px 5px 3px #e7413373;\n}\n\nbutton::before {\n  content: \"\";\n  background-image: url(\"data:image/svg+xml;base64,\");\n  background-size: 100%;\n  background-repeat: no-repeat;\n  color: transparent;\n  position: relative;\n  width: 50px;\n  height: 50px;\n  display: block;\n  margin-right: 5px;\n  transition: all .9s ease-in-out;\n}\n\nbutton:hover:before {\n  background-image: url(\"data:image/svg+xml;base64,\");\n  transition: all .9s ease-in-out;\n  transform: rotate(-1turn);\n}",
