    css: "/* From Uiverse.io by gharsh11032000 - Tags: gradient, button, dark, hover effect */\n.button {\n  position: relative;\n  width: 120px;\n  height: 40px;\n  background-color: #000;\n  display: flex;\n  align-items: center;\n  color: white;\n  flex-direction: column;\n  justify-content: center;\n  border: none;\n  padding: 12px;\n  gap: 12px;\n  border-radius: 8px;\n  cursor: pointer;\n}\n\n.button::before {\n  content: '';\n  position: absolute;\n  inset: 0;\n  left: -4px;\n  top: -1px;\n  margin: auto;\n  width: 128px;\n  height: 48px;\n  border-radius: 10px;\n  background: linear-gradient(-45deg, #e81cff 0%, #40c9ff 100% );\n  z-index: -10;\n  pointer-events: none;\n  transition: all 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n}\n\n.button::after {\n  content: \"\";\n  z-index: -1;\n  position: absolute;\n  inset: 0;\n  background: linear-gradient(-45deg, #fc00ff 0%, #00dbde 100% );\n  transform: translate3d(0, 0, 0) scale(0.95);\n  filter: blur(20px);\n}\n\n.button:hover::after {\n  filter: blur(30px);\n}\n\n.button:hover::before {\n  transform: rotate(-180deg);\n}\n\n.button:active::before {\n  scale: 0.7;\n}",
