    css: "/* From Uiverse.io by satyamchaudharydev - Tags: 3d, button */\nbutton {\n  --bg: #e74c3c;\n  --text-color: #fff;\n  position: relative;\n  width: 150px;\n  border: none;\n  background: var(--bg);\n  color: var(--text-color);\n  padding: 1em;\n  font-weight: bold;\n  text-transform: uppercase;\n  transition: 0.2s;\n  border-radius: 5px;\n  opacity: 0.8;\n  letter-spacing: 1px;\n  box-shadow: #c0392b 0px 7px 2px, #000 0px 8px 5px;\n}\n\nbutton:hover {\n  opacity: 1;\n}\n\nbutton:active {\n  top: 4px;\n  box-shadow: #c0392b 0px 3px 2px,#000 0px 3px 5px;\n}",
