    css: "/* From Uiverse.io by Yaya12085 - Tags: card */\n.card {\n  overflow: hidden;\n  position: relative;\n  background-color: #ffffff;\n  text-align: left;\n  border-radius: 0.5rem;\n  max-width: 290px;\n  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);\n}\n\n.header {\n  padding: 1.25rem 1rem 1rem 1rem;\n  background-color: #ffffff;\n}\n\n.image {\n  display: flex;\n  margin-left: auto;\n  margin-right: auto;\n  background-color: #FEE2E2;\n  flex-shrink: 0;\n  justify-content: center;\n  align-items: center;\n  width: 3rem;\n  height: 3rem;\n  border-radius: 9999px;\n}\n\n.image svg {\n  color: #DC2626;\n  width: 1.5rem;\n  height: 1.5rem;\n}\n\n.content {\n  margin-top: 0.75rem;\n  text-align: center;\n}\n\n.title {\n  color: #111827;\n  font-size: 1rem;\n  font-weight: 600;\n  line-height: 1.5rem;\n}\n\n.message {\n  margin-top: 0.5rem;\n  color: #6B7280;\n  font-size: 0.875rem;\n  line-height: 1.25rem;\n}\n\n.actions {\n  margin: 0.75rem 1rem;\n  background-color: #F9FAFB;\n}\n\n.desactivate {\n  display: inline-flex;\n  padding: 0.5rem 1rem;\n  background-color: #DC2626;\n  color: #ffffff;\n  font-size: 1rem;\n  line-height: 1.5rem;\n  font-weight: 500;\n  justify-content: center;\n  width: 100%;\n  border-radius: 0.375rem;\n  border-width: 1px;\n  border-color: transparent;\n  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);\n}\n\n.cancel {\n  display: inline-flex;\n  margin-top: 0.75rem;\n  padding: 0.5rem 1rem;\n  background-color: #ffffff;\n  color: #374151;\n  font-size: 1rem;\n  line-height: 1.5rem;\n  font-weight: 500;\n  justify-content: center;\n  width: 100%;\n  border-radius: 0.375rem;\n  border: 1px solid #D1D5DB;\n  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);\n}",
