    css: "/* From Uiverse.io by wojtek221221 - Source: wojtek221 - Tags: stats, cookies, cookie card, simple cards, Alerts, card design */\n.cookie-card {\n  border-radius: 15px;\n  width: 320px;\n  height: 200px;\n  background-color: #fff;\n}\n\n.cookie-title {\n  font-size: 20px;\n  position: relative;\n  left: 90px;\n  top: 15px;\n  font-weight: bold;\n  color: rgb(31 41 55);\n}\n\n.cookie-description {\n  position: relative;\n  top: 25px;\n  font-size: 15px;\n  text-align: center;\n  font-family: Verdana, Geneva, Tahoma, sans-serif;\n  color: rgb(75 85 99);\n}\n\n.cookies-policy {\n  color: rgb(31 41 55);\n  text-decoration: underline;\n}\n\n.cookies-policy:hover {\n  text-decoration: none;\n}\n\n.cookies-policy:active {\n  color: rgba(31, 41, 55, 0.61);\n  ;\n}\n\n.accept-button {\n  cursor: pointer;\n  font-weight: bold;\n  border-radius: 5px;\n  width: 85px;\n  height: 35px;\n  background-color: rgba(255, 255, 255, 0);\n  position: relative;\n  left: 115px;\n  top: 45px;\n}\n\n.accept-button:hover {\n  background-color: rgb(31 41 55);\n  color: #fff;\n  border: rgb(31 41 55);\n  ;\n}\n\n.accept-button:active {\n  font-weight: 100;\n}",
