    css: "/* From Uiverse.io by Zadrus  - Tags: simple, red, minimalist, gradient, loader, spinner, animated, gradients */\n.loading {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n}\n\n.diamond {\n  width: 50px;\n  height: 50px;\n  background-color: orange;\n  clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%);\n  margin: 5px;\n  opacity: 0;\n  animation: fade-in-out 1.5s ease-in-out infinite;\n}\n\n.diamond.middle {\n  transform: rotateY(180deg);\n}\n\n@keyframes fade-in-out {\n  0%,\n  100% {\n    opacity: 0;\n  }\n  50% {\n    opacity: 1;\n  }\n}\n\n.diamond {\n  background: linear-gradient(45deg, #ffba00, #ff6c00);\n}\n\n.diamond:nth-child(1) {\n  animation-delay: 0s;\n}\n\n.diamond.middle {\n  animation-delay: 0.5s;\n}\n\n.diamond:nth-child(3) {\n  animation-delay: 1s;\n}",
