    css: "/* From Uiverse.io by JkHuger - Tags: notification */\n.level-up-notification {\n  justify-content: center;\n  align-items: center;\n  flex-direction: column;\n  background-color: #FDD835;\n  border-radius: 10px;\n  font-weight: bold;\n  font-family: \"Courier New\", monospace;\n  box-shadow: 0 0 10px rgba(0, 0, 0, 0.5);\n  opacity: 0;\n  animation: scale-up 1.5s ease-in-out forwards, fade-out 0.5s ease-in-out forwards 21.5s;\n}\n\n.level-up-text {\n  text-align: center;\n  color: #fff;\n  font-size: 30px;\n  padding: 12px 20px;\n  font-weight: bold;\n  text-shadow: 2px 2px #000;\n}\n\n@keyframes confetti {\n  0% {\n    transform: translateY(-50%);\n  }\n\n  100% {\n    transform: translateY(100%);\n  }\n}\n\n@keyframes scale-up {\n  0% {\n    transform: scale(0);\n    opacity: 0;\n  }\n\n  100% {\n    transform: scale(1);\n    opacity: 1;\n  }\n}\n\n.level-up-notification:hover {\n  animation: none;\n}\n\n.level-up-notification:hover .confetti {\n  animation: confetti 0.5s ease-in-out forwards;\n}\n\n/* asd */\n\n.confetti-container {\n  user-select: none;\n  z-index: 10;\n}\n\n.confetti {\n  position: absolute;\n  left: 0;\n  right: 0;\n  display: flex;\n  /* width: 600px; */\n  /* height: 600px; */\n  /* overflow: hidden; */\n}\n\n.confetti .square {\n  width: 1rem;\n  height: 1rem;\n  background-color: var(--bg);\n  transform: rotate(-140deg);\n}\n\n.confetti .rectangle {\n  width: 1rem;\n  height: 0.5rem;\n  background-color: var(--bg);\n}\n\n.confetti .hexagram {\n  width: 0;\n  height: 0;\n  border-left: 0.5rem solid transparent;\n  border-right: 0.5rem solid transparent;\n  border-bottom: 1rem solid var(--bg);\n  position: relative;\n}\n\n.confetti .hexagram:after {\n  content: \"\";\n  width: 0;\n  height: 0;\n  border-left: 0.5rem solid transparent;\n  border-right: 0.5rem solid transparent;\n  border-top: 1rem solid var(--bg);\n  position: absolute;\n  top: 0.33rem;\n  left: -0.5rem;\n}\n\n.confetti .pentagram {\n  width: 0rem;\n  height: 0rem;\n  display: block;\n  margin: 0.5rem 0;\n  border-right: 1rem solid transparent;\n  border-bottom: 0.7rem solid var(--bg);\n  border-left: 1rem solid transparent;\n  transform: rotate(35deg);\n  position: relative;\n}\n\n.confetti .pentagram:before {\n  content: \"\";\n  width: 0;\n  height: 0;\n  display: block;\n  border-bottom: 0.8rem solid var(--bg);\n  border-left: 0.3rem solid transparent;\n  border-right: 0.3rem solid transparent;\n  transform: rotate(-35deg);\n  position: absolute;\n  top: -0.45rem;\n  left: -0.65rem;\n}\n\n.confetti .pentagram:after {\n  content: \"\";\n  width: 0rem;\n  height: 0rem;\n  display: block;\n  border-right: 1rem solid transparent;\n  border-bottom: 0.7rem solid var(--bg);\n  border-left: 1rem solid transparent;\n  transform: rotate(-70deg);\n  position: absolute;\n  top: 0.03rem;\n  left: -1.05rem;\n}\n\n.confetti .dodecagram {\n  background: var(--bg);\n  width: 0.8rem;\n  height: 0.8rem;\n  position: relative;\n}\n\n.confetti .dodecagram:before {\n  content: \"\";\n  height: 0.8rem;\n  width: 0.8rem;\n  background: var(--bg);\n  transform: rotate(30deg);\n  position: absolute;\n  top: 0;\n  left: 0;\n}\n\n.confetti .dodecagram:after {\n  content: \"\";\n  height: 0.8rem;\n  width: 0.8rem;\n  background: var(--bg);\n  transform: rotate(60deg);\n  position: absolute;\n  top: 0;\n  left: 0;\n}\n\n.confetti .wavy-line {\n  position: relative;\n}\n\n.confetti .wavy-line::after,\n.confetti .wavy-line::before {\n  content: \"\";\n  height: 1rem;\n  width: 8rem;\n  background-size: 2rem 1rem;\n  position: absolute;\n  left: -9rem;\n  transform: rotate(90deg);\n}\n\n.confetti .wavy-line::before {\n  background-image: linear-gradient(\n    45deg,\n    transparent,\n    transparent 50%,\n    var(--bg) 50%,\n    transparent 60%\n  );\n  top: 1rem;\n}\n\n.confetti .wavy-line::after {\n  background-image: linear-gradient(\n    -45deg,\n    transparent,\n    transparent 50%,\n    var(--bg) 50%,\n    transparent 60%\n  );\n}\n\n.confetti i {\n  width: 3rem;\n  height: 3rem;\n  margin: 0 0.2rem;\n  animation-name: confetti;\n  animation-timing-function: linear;\n  animation-iteration-count: infinite;\n  animation-duration: calc(70s / var(--speed));\n}\n\n.confetti i:nth-child(even) {\n  transform: rotate(90deg);\n}\n\n@keyframes confetti {\n  0% {\n    transform: translateY(-500px);\n  }\n\n  100% {\n    transform: translateY(500px);\n  }\n}",
