    css: "/* From Uiverse.io by Mr-Roy-alt - Tags: form, sign-up */\n.form {\n  background-color: white;\n  padding: 3.125em;\n  border-radius: 10px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  box-shadow: 5px 5px 15px -1px rgba(0,0,0,0.75);\n}\n\n.signup {\n  color: rgb(77, 75, 75);\n  text-transform: uppercase;\n  letter-spacing: 2px;\n  display: block;\n  font-weight: bold;\n  font-size: x-large;\n  margin-bottom: 0.5em;\n}\n\n.form--input {\n  width: 100%;\n  margin-bottom: 1.25em;\n  height: 40px;\n  border-radius: 5px;\n  border: 1px solid gray;\n  padding: 0.8em;\n  font-family: 'Inter', sans-serif;\n  outline: none;\n}\n\n.form--input:focus {\n  border: 1px solid #639;\n  outline: none;\n}\n\n.form--marketing {\n  display: flex;\n  margin-bottom: 1.25em;\n  align-items: center;\n}\n\n.form--marketing > input {\n  margin-right: 0.625em;\n}\n\n.form--marketing > label {\n  color: grey;\n}\n\n.checkbox, input[type=\"checkbox\"] {\n  accent-color: #639;\n}\n\n.form--submit {\n  width: 50%;\n  padding: 0.625em;\n  border-radius: 5px;\n  color: white;\n  background-color: #639;\n  border: 1px dashed #639;\n  cursor: pointer;\n}\n\n.form--submit:hover {\n  color: #639;\n  background-color: white;\n  border: 1px dashed #639;\n  cursor: pointer;\n  transition: 0.5s;\n}",
